import { GoogleGenAI } from "@google/genai";
import { Product } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getProductRecommendations(query: string, products: Product[]) {
  const model = 'gemini-3-flash-preview';

  const productContext = products.map(p => `- ${p.name}: ${p.description} ($${p.price})`).join('\n');

  const prompt = `
    You are a professional shopping assistant for "NexusModern".
    A user asks: "${query}"

    Here is our current inventory:
    ${productContext}

    Based on the user's query and our inventory, suggest 2-3 products. Explain why they are a good fit. 
    Keep it concise and friendly.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "I'm having a bit of trouble accessing my recommendations right now. Feel free to browse our categories!";
  }
}

