import React, { useState, useMemo, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { AdminPanel } from './components/AdminPanel';
import { CartDrawer } from './components/CartDrawer';
import { Product, CartItem, User, View, CATEGORIES } from './types';
import { INITIAL_PRODUCTS } from './constants';
import { getProductRecommendations } from './services/geminiService';

const App: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>({ id: '1', name: 'Alex Rivera', email: 'alex@example.com', isAdmin: true });
  const [isCartOpen, setIsCartOpen] = useState(false);

  // AI State
  const [aiInput, setAiInput] = useState('');
  const [aiResponse, setAiResponse] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Computed
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const cartCount = useMemo(() => cart.reduce((sum, item) => sum + item.quantity, 0), [cart]);

  // Handlers
  const handleAddToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const handleUpdateQuantity = (id: string, q: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: q } : item));
  };

  const handleRemoveFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const handleAddProduct = (newP: Omit<Product, 'id'>) => {
    const p: Product = { ...newP, id: Date.now().toString() };
    setProducts(prev => [p, ...prev]);
  };

  const handleDeleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const handleAiConsult = async () => {
    if (!aiInput.trim()) return;
    setIsAiLoading(true);
    setAiResponse(null);
    const result = await getProductRecommendations(aiInput, products);
    setAiResponse(result || "Error getting response.");
    setIsAiLoading(false);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar 
        currentView={currentView} 
        setView={setCurrentView} 
        cartCount={cartCount}
        user={user}
        onLogout={() => setUser(null)}
      />

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">
        {currentView === 'shop' && (
          <div className="space-y-8">
            {/* Hero / AI Assistant */}
            <div className="bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl p-8 md:p-12 text-white overflow-hidden relative shadow-2xl shadow-indigo-200">
              <div className="relative z-10 max-w-2xl">
                <h1 className="text-3xl md:text-5xl font-black mb-4 leading-tight">
                  The Future of Shopping is Here.
                </h1>
                <p className="text-indigo-100 text-lg mb-8 font-medium">
                  Experience a curated collection of premium gadgets and lifestyle essentials.
                </p>

                {/* AI Interaction */}
                <div className="bg-white/10 backdrop-blur-md p-6 rounded-2xl border border-white/20">
                  <p className="text-sm font-bold uppercase tracking-widest text-indigo-200 mb-3">AI Personal Shopper</p>
                  <div className="flex gap-2">
                    <input 
                      className="flex-1 bg-white/20 border-white/30 text-white placeholder:text-white/60 px-4 py-3 rounded-xl focus:ring-2 focus:ring-white outline-none"
                      placeholder="Ask me: 'I need a premium gadget for my desk setup'..."
                      value={aiInput}
                      onChange={e => setAiInput(e.target.value)}
                      onKeyPress={e => e.key === 'Enter' && handleAiConsult()}
                    />
                    <button 
                      onClick={handleAiConsult}
                      disabled={isAiLoading}
                      className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-bold hover:bg-indigo-50 transition-colors shadow-lg active:scale-95 disabled:opacity-50"
                    >
                      {isAiLoading ? 'Thinking...' : 'Consult'}
                    </button>
                  </div>
                  {aiResponse && (
                    <div className="mt-4 p-4 bg-white/90 text-indigo-900 rounded-xl text-sm animate-in fade-in slide-in-from-top-2">
                      <p className="font-semibold mb-1">NexusAI Suggests:</p>
                      <p>{aiResponse}</p>
                    </div>
                  )}
                </div>
              </div>
              <div className="absolute right-0 top-0 bottom-0 w-1/3 bg-indigo-500/10 blur-3xl rounded-full translate-x-1/2"></div>
            </div>

            {/* Filters */}
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-2xl border border-slate-200">
              <div className="flex gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0 scrollbar-hide">
                {CATEGORIES.map(cat => (
                  <button 
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`px-4 py-2 rounded-xl text-sm font-semibold transition-all whitespace-nowrap
                      ${selectedCategory === cat 
                        ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>

              <div className="relative w-full md:w-72">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
                <input 
                  type="text" 
                  placeholder="Search products..."
                  className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                />
              </div>
            </div>

            {/* Product Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredProducts.length > 0 ? (
                filteredProducts.map(product => (
                  <ProductCard 
                    key={product.id} 
                    product={product} 
                    onAddToCart={handleAddToCart}
                    onViewDetails={(p) => console.log('Viewing details for:', p.name)}
                  />
                ))
              ) : (
                <div className="col-span-full py-20 text-center">
                   <div className="bg-slate-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                   </div>
                   <h3 className="text-xl font-bold text-slate-900">No products found</h3>
                   <p className="text-slate-500 mt-2">Try adjusting your filters or search terms.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {currentView === 'admin' && (
          <AdminPanel 
            products={products}
            onAddProduct={handleAddProduct}
            onDeleteProduct={handleDeleteProduct}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 pt-16 pb-8">
        <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-4 gap-12 mb-12">
            <div className="col-span-1 md:col-span-1">
                 <div className="flex items-center gap-2 mb-6">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
                        <span className="text-white font-bold">N</span>
                    </div>
                    <span className="text-xl font-bold text-slate-900">NexusModern</span>
                </div>
                <p className="text-slate-500 text-sm leading-relaxed">
                    Premium tech and lifestyle boutique. We bring you the finest selection of future-forward products.
                </p>
            </div>
            <div>
                <h4 className="font-bold text-slate-900 mb-6">Shop</h4>
                <ul className="space-y-4 text-sm text-slate-500 font-medium">
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Electronics</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Gadgets</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Lifestyle</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">New Arrivals</li>
                </ul>
            </div>
            <div>
                <h4 className="font-bold text-slate-900 mb-6">Company</h4>
                <ul className="space-y-4 text-sm text-slate-500 font-medium">
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">About Us</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Careers</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Affiliates</li>
                </ul>
            </div>
            <div>
                <h4 className="font-bold text-slate-900 mb-6">Support</h4>
                <ul className="space-y-4 text-sm text-slate-500 font-medium">
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Shipping Info</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Refund Policy</li>
                    <li className="hover:text-indigo-600 cursor-pointer transition-colors">Contact</li>
                </ul>
            </div>
        </div>
        <div className="max-w-7xl mx-auto px-4 border-t border-slate-100 pt-8 flex flex-col md:flex-row justify-between items-center gap-4">
            <p className="text-sm text-slate-400">© 2024 NexusModern Store. All rights reserved.</p>
            <div className="flex gap-6">
                {/* Social icons placeholder */}
                <div className="w-5 h-5 bg-slate-200 rounded-full"></div>
                <div className="w-5 h-5 bg-slate-200 rounded-full"></div>
                <div className="w-5 h-5 bg-slate-200 rounded-full"></div>
            </div>
        </div>
      </footer>

      <CartDrawer 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        items={cart}
        onRemove={handleRemoveFromCart}
        onUpdateQuantity={handleUpdateQuantity}
        onCheckout={() => alert('Proceeding to secure payment integration (Stripe)...')}
      />
    </div>
  );
};

export default App;

