        {currentView === 'shop' && (
          <div className="space-y-12">
            {/* Immersive Science-Themed Hero Section */}
            <div 
              className="relative rounded-[2.5rem] overflow-hidden min-h-[550px] flex items-center shadow-2xl border border-white/10"
              style={{
                backgroundImage: 'url("https://images.unsplash.com/photo-1635070041078-e363dbe005cb?auto=format&fit=crop&q=80&w=2000")',
                backgroundSize: 'cover',
                backgroundPosition: 'center'
              }}
            >
              {/* Deep Gradient Overlay for Readability */}
              <div className="absolute inset-0 bg-gradient-to-br from-black/80 via-black/40 to-transparent"></div>

              {/* Abstract Particle Overlay */}
              <div className="absolute inset-0 opacity-30 pointer-events-none mix-blend-screen">
                  <div className="absolute top-1/4 left-1/3 w-64 h-64 bg-indigo-500/20 rounded-full blur-[100px] animate-pulse"></div>
                  <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-500/10 rounded-full blur-[120px] animate-pulse delay-700"></div>
              </div>

              <div className="relative z-10 max-w-3xl px-8 md:px-16 py-12">
                <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-indigo-500/20 border border-indigo-400/30 text-indigo-200 text-xs font-bold uppercase tracking-[0.2em] mb-8 backdrop-blur-md">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                  </svg>
                  Precision Digital Engineering
                </div>

                <h1 className="text-5xl md:text-7xl font-black mb-8 leading-tight text-white tracking-tight">
                  Where Science Meets <br/>
