                    <span className="flex h-2 w-2 rounded-full bg-blue-400 animate-pulse"></span>
                    AI Consultative Intelligence
                  </p>
                  <div className="flex flex-col sm:flex-row gap-3">
                    <input 
                      className="flex-1 bg-white/10 border-white/20 text-white placeholder:text-slate-400 px-6 py-4 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                      placeholder="Ask about SEO, Web Dev, or Design..."
                      value={aiInput}
                      onChange={e => setAiInput(e.target.value)}
                      onKeyPress={e => e.key === 'Enter' && handleAiConsult()}
                    />
                    <button 
