              {/* Dynamic Particle Background (CSS Only) */}
              <div className="absolute inset-0 opacity-20 mix-blend-screen pointer-events-none">
                <div className="absolute top-0 left-0 w-full h-full overflow-hidden">
                  {[...Array(20)].map((_, i) => (
                    <div 
                      key={i} 
                      className="absolute bg-blue-400 rounded-full blur-xl animate-pulse"
                      style={{
                        width: Math.random() * 100 + 20 + 'px',
                        height: Math.random() * 100 + 20 + 'px',
                        top: Math.random() * 100 + '%',
                        left: Math.random() * 100 + '%',
                        animationDelay: Math.random() * 5 + 's',
                        opacity: Math.random() * 0.5
                      }}
                    />
                  ))}
                </div>
              </div>

              <div className="relative z-10 max-w-3xl px-8 md:px-16 py-12">
                <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-200 text-xs font-black uppercase tracking-[0.2em] mb-8 backdrop-blur-md">
